svg.script:
try {
var btnEncode = document.getElementById('btnEncode');
var btnDecode = document.getElementById('btnDecode');
var btnSwap = document.getElementById('btnSwap');
var txtPlain = document.getElementById('plaintext');
var txtEmoji = document.getElementById('emojitext');
var inpEmoji0 = document.getElementById('emoji0');
var inpEmoji1 = document.getElementById('emoji1');

// Découpe une chaîne en tableau de caractères unicode (gère les paires de substitution)
function getUnicodeChars(str) {
if (!str) return [];
var chars = [];
var i = 0;
while (i < str.length) {
    var code = str.charCodeAt(i);
    if (code >= 0xD800 && code <= 0xDBFF && i + 1 < str.length) {
            var nextCode = str.charCodeAt(i + 1);
            if (nextCode >= 0xDC00 && nextCode <= 0xDFFF) {
                chars.push(str.substring(i, i + 2));
                i += 2;
                } else {
                chars.push(str.charAt(i));
                i++;
                }
                } else {
                chars.push(str.charAt(i));
                i++;
                }
                }
                return chars;
                }

                function getFirstCodePoint(str) {
                if (!str) return "";
                var chars = getUnicodeChars(str.trim());
                return chars.length > 0 ? chars[0] : "";
                }

                // --- ENCODAGE ---
                btnEncode.addEventListener('click', function() {
                try {
                var e0 = getFirstCodePoint(inpEmoji0.value);
                var e1 = getFirstCodePoint(inpEmoji1.value);
                var text = txtPlain.value;

                if (!e0 || !e1) {
                e0 = "0"; e1 = "1";
                inpEmoji0.value = "0";
                inpEmoji1.value = "1";
                }

                var bytes = new TextEncoder().encode(text);
                var result = "";

                for (var i = 0; i < bytes.length; i++) {
                    var binString = bytes[i].toString(2);
                    while(binString.length < 8) {
                        binString = "0" + binString;
                        }

                        for (var j = 0; j < 8; j++) {
                            result += (binString[j] === '0') ? e0 : e1;
                            }
                            result += " ";
                            }

                            txtEmoji.value = result.trim();
                            } catch(err) {
                            txtPlain.value = "Erreur d'encodage : " + err.message;
                            }
                            });

                            // --- DÉCODAGE ---
                            btnDecode.addEventListener('click', function() {
                            try {
                            var text = txtEmoji.value;
                            if (!text || text.trim() === "") {
                            txtPlain.value = "Erreur : Aucun message à décoder dans la zone ci-dessous.";
                            return;
                            }

                            var chars = getUnicodeChars(text);
                            var unique = [];
                            var freq = {};

                            // Compter les caractères uniques (en ignorant les espaces)
                            for (var i = 0; i < chars.length; i++) {
                                var c = chars[i];
                                if (c.trim() !== "") {
                                if (freq[c] === undefined) {
                                freq[c] = 0;
                                unique.push(c);
                                }
                                freq[c]++;
                                }
                                }

                                if (unique.length < 2) {
                                    txtPlain.value = "Erreur : Le message doit contenir au moins deux caractères différents.";
                                    return;
                                    }

                                    var e0 = "";
                                    var e1 = "";

                                    // 1. Vérifier si les emojis définis par l'utilisateur sont valides et présents
                                    var userE0 = getFirstCodePoint(inpEmoji0.value);
                                    var userE1 = getFirstCodePoint(inpEmoji1.value);

                                    if (userE0 && userE1 && userE0 !== userE1 && freq[userE0] !== undefined && freq[userE1] !== undefined) {
                                    e0 = userE0;
                                    e1 = userE1;
                                    } else {
                                    // 2. Détection automatique
                                    if (unique.length === 2) {
                                    e0 = unique[0];
                                    e1 = unique[1];
                                    inpEmoji0.value = e0;
                                    inpEmoji1.value = e1;
                                    } else {
                                    txtPlain.value = "Erreur : " + unique.length + " caractères uniques détectés. Veuillez définir manuellement les emojis 0 et 1 dans les paramètres.";
                                    return;
                                    }
                                    }

                                    var binaryString = "";
                                    for (var i = 0; i < chars.length; i++) {
                                        if (chars[i] === e0) binaryString += "0";
                                        else if (chars[i] === e1) binaryString += "1";
                                        }

                                        if (binaryString.length === 0) {
                                        txtPlain.value = "Erreur : Aucun emoji correspondant trouvé.";
                                        return;
                                        }

                                        // Si la longueur n'est pas un multiple de 8, on comble avec des 0 (par sécurité)
                                        while (binaryString.length % 8 !== 0) {
                                        binaryString += "0";
                                        }

                                        var bytes = [];
                                        for (var i = 0; i < binaryString.length; i += 8) {
                                            var byteStr = binaryString.substring(i, i + 8);
                                            bytes.push(parseInt(byteStr, 2));
                                            }

                                            var uint8Array = new Uint8Array(bytes);
                                            var decodedText = new TextDecoder('utf-8').decode(uint8Array);
                                            txtPlain.value = decodedText;

                                            } catch (err) {
                                            txtPlain.value = "Erreur de décodage : " + err.message;
                                            }
                                            });

                                            // --- INVERSER ---
                                            btnSwap.addEventListener('click', function() {
                                            var tmp = inpEmoji0.value;
                                            inpEmoji0.value = inpEmoji1.value;
                                            inpEmoji1.value = tmp;
                                            btnDecode.click(); // Relance le décodage automatiquement
                                            });

                                            } catch(err) {
                                            var pt = document.getElementById('plaintext');
                                            if(pt) pt.value = "ERREUR D'INITIALISATION: " + err.message;
                                            }
